var e=JSON.parse(`[{"id":"fb-joues-porc-cidre-calvados","name":"Joues de porc braisées au cidre et au calvados, pommes fruits et purée","description":"Des joues de porc fondantes, braisées trois heures dans le cidre brut et le bouillon d’os, flambées au calvados. Quartiers de pommes poêlés au beurre et purée crémeuse à la crème d’Isigny.","emoji":"🍎","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":180,"difficulty":"facile","servings":4,"ingredients":[{"id":"porc-echine","qty":900,"unit":"g","note":"joues de porc parées (environ 10)"},{"id":"cidre","qty":500,"unit":"ml","note":"cidre brut fermier"},{"id":"bouillon-boeuf","qty":300,"unit":"ml","note":"fond de veau maison"},{"id":"oignon","qty":2,"unit":"piece","note":"émincés"},{"id":"carotte","qty":1,"unit":"piece","note":"en rondelles"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"pomme","qty":3,"unit":"piece","note":"reinettes, en quartiers"},{"id":"pomme-de-terre-farineuse","qty":600,"unit":"g","note":"bintje"},{"id":"beurre","qty":40,"unit":"g"},{"id":"creme-fraiche","qty":80,"unit":"ml","note":"crème crue d’Isigny"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez les joues et salez-les. Dans une cocotte en fonte, faites chauffer la graisse de canard à feu vif et colorez les joues en deux fournées, 3 min par face, jusqu’à ce qu’elles soient bien brunes. Réservez.","Baissez à feu moyen, ajoutez oignons et carotte, faites-les suer 5 min en grattant les sucs. Remettez les joues, versez un trait de cidre (ou 2 c. à soupe de calvados si vous en avez) et laissez évaporer 1 min.","Mouillez avec le reste du cidre et le bouillon, ajoutez thym et laurier. Portez à frémissement, couvrez et laissez mijoter 2 h 45 à feu très doux (ou au four à 150 °C) : la joue doit se couper à la cuillère.","Retirez les joues, filtrez le jus et faites-le réduire 10 à 15 min à feu vif jusqu’à ce qu’il nappe la cuillère. Remettez les joues dans la sauce pour les lustrer.","Pendant ce temps, cuisez les pommes de terre épluchées 25 min dans l’eau salée frémissante. Écrasez-les au presse-purée avec 25 g de beurre et la crème chaude, salez.","Faites dorer les quartiers de pomme 6 min dans le reste du beurre à feu moyen, en les retournant, jusqu’à ce qu’ils soient caramélisés mais encore fermes.","Servez les joues nappées de sauce avec la purée et les pommes poêlées."],"tags":["mijoté","week-end","réconfortant","riche en collagène","prise de masse","fermenté"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","fruite","umami"],"tips":"Pourquoi c’est nutritif : la joue est un muscle très travaillé, riche en collagène qui se transforme en gélatine pendant la longue cuisson, et le bouillon d’os renforce encore la sauce. Se réchauffe parfaitement le lendemain."},{"id":"fb-parmentier-queue-boeuf","name":"Parmentier de queue de bœuf au vin rouge, purée de panais","description":"La queue de bœuf braisée au vin rouge puis effilochée, liée par sa sauce gélatineuse, sous une purée de pommes de terre et de panais gratinée au comté.","emoji":"🥘","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":40,"cookTime":240,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"boeuf-queue","qty":1500,"unit":"g","note":"tronçonnée par le boucher"},{"id":"vin-rouge","qty":500,"unit":"ml","note":"côtes-du-rhône"},{"id":"bouillon-boeuf","qty":500,"unit":"ml"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"pomme-de-terre-farineuse","qty":500,"unit":"g"},{"id":"panais","qty":500,"unit":"g"},{"id":"beurre","qty":35,"unit":"g"},{"id":"lait","qty":150,"unit":"ml"},{"id":"comte","qty":50,"unit":"g","note":"râpé"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 150 °C. Dans une grande cocotte, saisissez les tronçons de queue dans la graisse de canard à feu vif, 8 à 10 min au total, jusqu’à ce qu’ils soient bien bruns sur toutes les faces. Réservez.","À feu moyen, faites revenir oignons et carotte coupés en dés 5 min, ajoutez l’ail écrasé et le concentré de tomate, remuez 1 min. Déglacez au vin rouge et faites bouillir 3 min.","Remettez la viande, ajoutez le bouillon, le thym et le laurier : le liquide doit presque couvrir. Couvrez et enfournez 3 h 30, jusqu’à ce que la chair se détache seule de l’os.","Sortez les tronçons, laissez tiédir 10 min et effilochez la viande à la fourchette en écartant os et gras dur. Dégraissez la sauce, faites-la réduire 10 min à feu vif jusqu’à consistance sirupeuse et mélangez-y la viande.","Cuisez pommes de terre et panais épluchés et coupés en morceaux 20 min à l’eau salée. Égouttez et écrasez avec le beurre et le lait chaud.","Montez le four à 200 °C. Étalez la viande dans un plat, couvrez de purée, parsemez de comté et enfournez 20 min, jusqu’à ce que le dessus soit doré et bouillonnant sur les bords."],"tags":["mijoté","week-end","familial","riche en collagène","batch cooking","four"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","reconfortant"],"tips":"Pourquoi c’est nutritif : la queue de bœuf apporte collagène, gélatine et moelle ; le panais adoucit la purée sans ajouter d’oxalates. Se congèle très bien en portions avant gratinage."},{"id":"fb-plat-de-cotes-cahors-pruneaux","name":"Plat de côtes braisé au Cahors et aux pruneaux, polenta au beurre","description":"Des plats de côtes laqués par une sauce au vin de Cahors, aux pruneaux d’Agen et au piment d’Espelette, servis sur une polenta crémeuse.","emoji":"🍷","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":210,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-plat-de-cote","qty":1200,"unit":"g","note":"en morceaux de 8 cm"},{"id":"vin-rouge","qty":500,"unit":"ml","note":"Cahors"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"pruneaux","qty":16,"unit":"piece","note":"pruneaux d’Agen dénoyautés"},{"id":"echalote","qty":4,"unit":"piece"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"thym","qty":3,"unit":"brin"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"polenta","qty":200,"unit":"g"},{"id":"lait","qty":400,"unit":"ml"},{"id":"eau","qty":600,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez les plats de côtes la veille ou au moins 1 h avant. Faites chauffer le four à 150 °C.","Dans une cocotte, faites fondre la graisse de canard à feu vif et colorez la viande 3 min par face, jusqu’à une belle croûte brune. Retirez-la et jetez l’excès de graisse en n’en gardant qu’une cuillère.","Faites revenir les échalotes émincées et l’ail 3 min à feu moyen. Versez le vin, grattez les sucs et laissez bouillir 5 min. Ajoutez le bouillon, le thym et le piment d’Espelette, puis remettez la viande.","Couvrez et enfournez 3 h. Ajoutez les pruneaux pour les 45 dernières minutes : ils doivent gonfler sans se défaire.","Retirez la viande et les pruneaux, dégraissez la sauce à la louche puis réduisez-la 10 min à feu vif jusqu’à ce qu’elle soit sirupeuse et brillante.","Portez le lait et l’eau salés à ébullition, versez la polenta en pluie en fouettant, puis cuisez 10 min à feu doux en remuant (5 min pour une polenta instantanée). Incorporez le beurre hors du feu.","Dressez la polenta, posez les plats de côtes et les pruneaux, nappez de sauce."],"tags":["mijoté","week-end","prise de masse","calorique","riche en collagène","sans gluten"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","fruite","reconfortant"],"tips":"Pourquoi c’est nutritif : la viande sur l’os, cuite longtemps, libère collagène et minéraux dans la sauce. Préparé la veille, il se dégraisse facilement une fois froid."},{"id":"fb-jambonneau-riesling-chou","name":"Jambonneau braisé au riesling, chou vert fondant et pommes de terre","description":"Un jarret de porc braisé lentement au riesling et aux baies de genièvre, sur un chou vert qui confit dans le jus, avec des pommes de terre cuites dessous. L’Alsace sans choucroute.","emoji":"🍖","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":180,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"porc-jarret","qty":1700,"unit":"g","note":"2 jarrets arrière frais"},{"id":"vin-blanc","qty":400,"unit":"ml","note":"riesling"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"chou-vert","qty":800,"unit":"g","note":"chou de Milan"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"pomme-de-terre","qty":700,"unit":"g","note":"à chair ferme"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"carvi"},{"id":"girofle","qty":2,"unit":"pincee","note":"2 clous de girofle"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"moutarde","qty":2,"unit":"cas","note":"à l’ancienne, pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 160 °C. Dans une grande cocotte, dorez les jarrets dans 1 c. à soupe de graisse de canard à feu moyen-vif, 10 min en les tournant, jusqu’à ce que la couenne soit bien colorée.","Ajoutez les oignons piqués des clous de girofle, le laurier, le carvi, le riesling et le bouillon. Portez à frémissement, couvrez et enfournez 2 h.","Pendant ce temps, coupez le chou en 8 quartiers, retirez le trognon et blanchissez-les 5 min à l’eau bouillante salée. Égouttez.","Sortez la cocotte, glissez le chou et les pommes de terre épluchées et coupées en deux autour des jarrets, en les enfonçant dans le jus. Arrosez du reste de graisse, couvrez et remettez 1 h au four.","Les 15 dernières minutes, retirez le couvercle et montez à 200 °C pour dorer la couenne. La viande doit se détacher de l’os à la fourchette.","Désossez les jarrets à table et servez avec le chou, les pommes de terre, un peu de jus et la moutarde à l’ancienne."],"tags":["mijoté","familial","riche en collagène","week-end","économique"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","umami"],"tips":"Pourquoi c’est nutritif : le jarret, os et couenne compris, est l’un des morceaux les plus riches en collagène ; le chou apporte vitamine C et fibres. Les restes de viande font une excellente salade tiède le lendemain."},{"id":"fb-gras-double-lyonnaise","name":"Gras-double à la lyonnaise, oignons confits, riz pilaf et frisée","description":"Le classique des bouchons : lanières de gras-double rissolées au beurre avec beaucoup d’oignons blonds, déglacées au vinaigre et au persil, servi avec un riz pilaf et une frisée à l’œuf.","emoji":"🧅","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":45,"difficulty":"facile","servings":2,"ingredients":[{"id":"tripes","qty":550,"unit":"g","note":"gras-double précuit, en lanières"},{"id":"oignon","qty":3,"unit":"piece","note":"émincés finement"},{"id":"beurre","qty":40,"unit":"g"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin"},{"id":"vin-blanc","qty":50,"unit":"ml"},{"id":"persil","qty":8,"unit":"g","note":"ciselé"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"riz-blanc","qty":140,"unit":"g"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"endive","qty":1,"unit":"piece","note":"frisée ou chicorée"},{"id":"oeuf","qty":2,"unit":"piece","note":"mollets, pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez soigneusement le gras-double sur un torchon : il doit être bien sec pour dorer.","Dans une sauteuse, faites fondre 20 g de beurre à feu moyen et confisez les oignons 20 min en remuant souvent, jusqu’à ce qu’ils soient blonds et fondants. Réservez.","Nacrez le riz 2 min dans 1 c. à café de graisse de canard, versez le bouillon chaud, couvrez et cuisez 12 min à feu doux. Laissez reposer 5 min hors du feu.","Dans une grande poêle, chauffez le reste de graisse à feu vif et faites rissoler le gras-double 10 à 12 min, en remuant peu, jusqu’à ce que les bords soient dorés et croustillants.","Ajoutez les oignons et l’ail haché, mélangez 2 min. Déglacez avec le vinaigre et le vin blanc, laissez réduire 1 min, puis ajoutez le reste de beurre et le persil. Poivrez généreusement.","Cuisez les œufs 6 min à l’eau bouillante et écalez-les. Servez le gras-double avec le riz, la frisée en lanières assaisonnée d’un trait de vinaigre et l’œuf mollet posé dessus."],"tags":["abats","économique","une poêle","riche en collagène","riche en protéines"],"seasons":["automne","hiver","printemps"],"technique":"poele","flavors":["acidule","umami","reconfortant"],"tips":"Pourquoi c’est nutritif : les tripes sont pauvres en graisse mais riches en collagène, en zinc et en vitamine B12, et l’œuf complète les protéines. Achetez le gras-double déjà blanchi chez le tripier."},{"id":"fb-coeur-boeuf-poivre-vert-potimarron","name":"Cœur de bœuf poêlé sauce au poivre vert, purée de potimarron","description":"Des tranches épaisses de cœur de bœuf saisies rosées, une sauce crémée au poivre vert et au cognac, et une purée de potimarron au beurre noisette.","emoji":"❤️","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"coeur-boeuf","qty":380,"unit":"g","note":"paré, en tranches de 2 cm"},{"id":"potimarron","qty":600,"unit":"g","note":"avec la peau"},{"id":"beurre","qty":40,"unit":"g"},{"id":"creme-liquide","qty":100,"unit":"ml"},{"id":"bouillon-boeuf","qty":80,"unit":"ml"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"poivre","qty":1,"unit":"au-gout","note":"poivre vert en saumure : 1 c. à soupe"},{"id":"vin-rouge","qty":30,"unit":"ml","note":"ou cognac"},{"id":"riz-blanc","qty":80,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Retirez au couteau les vaisseaux et les parties nerveuses du cœur, puis taillez-le en tranches de 2 cm. Sortez-les 20 min avant la cuisson.","Coupez le potimarron en cubes (peau comprise) et cuisez-le 15 min à la vapeur. Cuisez le riz 12 min à l’eau salée en parallèle.","Faites chauffer 20 g de beurre jusqu’à ce qu’il devienne noisette (couleur ambrée, odeur de noisette), versez-le sur le potimarron et mixez en purée lisse. Salez.","Dans une poêle en fonte très chaude, faites fondre 10 g de beurre et saisissez les tranches de cœur 2 min par face : elles doivent rester rosées à cœur, sinon elles durcissent. Réservez au chaud sous une feuille d’aluminium.","Dans la même poêle à feu moyen, faites suer l’échalote ciselée 1 min, flambez ou déglacez avec le vin, ajoutez le bouillon et réduisez de moitié (3 min). Versez la crème et le poivre vert égoutté, laissez épaissir 3 min, puis montez avec le reste de beurre.","Servez le cœur nappé de sauce, avec la purée de potimarron et le riz."],"tags":["abats","rapide","riche en protéines","économique","sans gluten"],"seasons":["automne","hiver"],"technique":"poele","flavors":["piquant","cremeux","umami"],"tips":"Pourquoi c’est nutritif : le cœur est un muscle maigre très riche en coenzyme Q10, fer héminique et vitamines B. Sa texture rappelle un steak : ne le cuisez jamais au-delà de rosé."},{"id":"fb-foie-agneau-raisins-cognac","name":"Foie d’agneau aux raisins et au cognac, purée céleri-pommes de terre","description":"Des tranches de foie d’agneau juste saisies au beurre, une poêlée de raisins blancs déglacée au cognac et au jus de viande, sur une purée de céleri-rave crémeuse.","emoji":"🍇","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"foie-agneau","qty":280,"unit":"g","note":"en tranches de 1 cm"},{"id":"raisin","qty":150,"unit":"g","note":"raisin blanc, coupé en deux"},{"id":"vin-rouge","qty":40,"unit":"ml","note":"cognac ou porto"},{"id":"bouillon-boeuf","qty":100,"unit":"ml"},{"id":"celeri-rave","qty":200,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":160,"unit":"g"},{"id":"lait","qty":100,"unit":"ml"},{"id":"beurre","qty":45,"unit":"g"},{"id":"farine-riz","qty":1,"unit":"cas"},{"id":"jambon-cru","qty":4,"unit":"piece","note":"tranches fines, en lanières"},{"id":"sauge","qty":4,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épluchez le céleri-rave et les pommes de terre, coupez-les en cubes et cuisez-les 20 min dans le lait additionné d’eau à hauteur, salée, à feu doux. Égouttez en gardant un peu de liquide et écrasez avec 20 g de beurre.","Faites croustiller les lanières de jambon cru 3 min à sec dans une poêle à feu moyen. Réservez.","Épongez le foie, passez-le très légèrement dans la farine de riz et tapotez pour retirer l’excédent.","Faites chauffer 15 g de beurre et les feuilles de sauge à feu vif jusqu’à ce qu’il mousse. Saisissez le foie 1 min 30 par face : il doit rester rosé au centre. Salez, poivrez et réservez sur une assiette chaude.","Dans la même poêle, faites sauter les raisins 2 min, déglacez au cognac, ajoutez le bouillon et réduisez 3 min. Hors du feu, incorporez le reste du beurre.","Dressez la purée, le foie, nappez de raisins et de sauce, et parsemez de jambon croustillant."],"tags":["abats","rapide","riche en protéines","sans gluten","une poêle"],"seasons":["automne"],"technique":"poele","flavors":["fruite","umami","cremeux"],"tips":"Pourquoi c’est nutritif : le foie concentre vitamine A, B12, folates, cuivre et fer. Une portion par semaine suffit ; le foie de porc ou de génisse convient aussi."},{"id":"fb-alicot-gesiers-coeurs-cepes","name":"Alicot languedocien aux gésiers, cœurs de canard et cèpes","description":"Le ragoût des abattis de canard du Sud-Ouest : gésiers, cœurs et cuisses mijotés dans un bouillon d’os à l’ail et à la tomate, avec cèpes et pommes de terre.","emoji":"🦆","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"gesiers","qty":400,"unit":"g","note":"gésiers frais, nettoyés"},{"id":"coeur-volaille","qty":300,"unit":"g","note":"cœurs de canard"},{"id":"canard-cuisse","qty":2,"unit":"piece","note":"coupées en deux à la jointure"},{"id":"champignon-forestier","qty":300,"unit":"g","note":"cèpes frais ou 40 g séchés réhydratés"},{"id":"pomme-de-terre","qty":600,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"tomates-concassees","qty":200,"unit":"g"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"bouillon-volaille","qty":500,"unit":"ml"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez les gésiers en deux et dénervez les cœurs. Dans une cocotte, faites dorer les morceaux de cuisse côté peau dans 1 c. à soupe de graisse de canard, 8 min à feu moyen, puis les gésiers et les cœurs 5 min.","Ajoutez l’oignon et la carotte en dés, puis 3 gousses d’ail écrasées, et faites revenir 5 min. Déglacez au vin blanc, laissez réduire 2 min.","Ajoutez les tomates, le bouillon, le thym et le laurier. Couvrez et laissez mijoter 1 h à feu doux : les gésiers doivent devenir tendres sous la dent.","Ajoutez les pommes de terre coupées en gros morceaux et poursuivez 30 min à couvert.","Pendant ce temps, faites sauter les cèpes en tranches dans le reste de graisse de canard à feu vif, 6 min, jusqu’à ce qu’ils soient dorés. Ajoutez le reste d’ail haché et le persil hors du feu.","Incorporez les cèpes dans la cocotte 5 min avant de servir. Rectifiez l’assaisonnement et servez bien chaud."],"tags":["abats","mijoté","économique","familial","réconfortant","sans gluten"],"seasons":["automne"],"technique":"mijote","flavors":["umami","reconfortant"],"tips":"Pourquoi c’est nutritif : gésiers et cœurs sont des muscles riches en fer, zinc et vitamines B pour un prix modique ; le bouillon d’os apporte la gélatine. Encore meilleur réchauffé."},{"id":"fb-moules-farcies-beurre-escargot","name":"Moules farcies au beurre d’escargot gratinées, riz au safran","description":"Des grosses moules ouvertes au vin blanc, garnies de beurre à l’ail, au persil et au jambon cru, gratinées au four et servies avec un riz au safran cuit dans leur jus.","emoji":"🦪","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":35,"cookTime":25,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"moule","qty":1600,"unit":"g","note":"grosses moules de bouchot"},{"id":"vin-blanc","qty":100,"unit":"ml","note":"muscadet"},{"id":"echalote","qty":2,"unit":"piece"},{"id":"beurre","qty":50,"unit":"g","note":"mou"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"persil","qty":10,"unit":"g"},{"id":"jambon-cru","qty":3,"unit":"piece","note":"haché très fin"},{"id":"comte","qty":30,"unit":"g","note":"râpé finement"},{"id":"riz-blanc","qty":160,"unit":"g"},{"id":"safran","qty":1,"unit":"pincee"},{"id":"oeuf","qty":2,"unit":"piece","note":"mollets, pour servir"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Grattez et rincez les moules ; jetez celles qui restent ouvertes après une pichenette. Dans une grande cocotte à feu vif, faites suer les échalotes ciselées 1 min, ajoutez le vin et les moules, couvrez et cuisez 4 à 5 min en secouant, jusqu’à ce qu’elles s’ouvrent.","Filtrez le jus de cuisson à travers un linge fin. Retirez une coquille vide à chaque moule et disposez les demi-coquilles garnies serrées sur une plaque.","Écrasez à la fourchette le beurre mou avec l’ail pressé, le persil haché, le jambon et le comté. Poivrez.","Cuisez le riz 12 min dans 350 ml de jus de moules complété d’eau (goûtez : il est déjà salé), avec le safran, à couvert et à feu doux.","Faites chauffer le gril du four. Déposez une noisette de beurre farci sur chaque moule et passez sous le gril 3 à 4 min, jusqu’à ce que le beurre grésille et que le dessus blondisse.","Cuisez les œufs 6 min à l’eau bouillante, écalez-les. Servez les moules brûlantes avec le riz safrané et l’œuf mollet."],"tags":["four","riche en protéines","sans gluten","week-end"],"seasons":["automne","hiver","printemps"],"technique":"four","flavors":["iode","herbace","grille"],"tips":"Pourquoi c’est nutritif : les moules sont une source exceptionnelle de vitamine B12, de fer, de zinc et d’iode, et le beurre aide à absorber les vitamines liposolubles. Les moules garnies se congèlent crues sur plaque, puis en sac."},{"id":"fb-merlu-koskera-palourdes","name":"Merlu koskera aux palourdes, asperges et œuf dur","description":"La recette de Saint-Jean-de-Luz : tranches de merlu pochées dans une sauce verte à l’ail, au persil et au vin blanc, avec palourdes, petits pois, asperges et pommes de terre.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"cabillaud","qty":400,"unit":"g","note":"merlu en tranches épaisses ou dos de lieu"},{"id":"palourde","qty":400,"unit":"g","note":"dégorgées 1 h dans l’eau salée"},{"id":"asperge","qty":6,"unit":"piece","note":"vertes"},{"id":"petits-pois","qty":120,"unit":"g"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"pomme-de-terre","qty":300,"unit":"g","note":"grenailles"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"ail","qty":4,"unit":"gousse","note":"en lamelles"},{"id":"farine-riz","qty":1,"unit":"cas"},{"id":"vin-blanc","qty":100,"unit":"ml"},{"id":"fumet-poisson","qty":200,"unit":"ml"},{"id":"persil","qty":10,"unit":"g","note":"haché"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Cuisez les grenailles 18 min à l’eau salée et les œufs 10 min dans une autre casserole ; écalez les œufs et coupez-les en quartiers. Blanchissez les pointes d’asperges et les petits pois 3 min.","Dans une large cassole ou sauteuse, faites chauffer l’huile d’olive à feu doux et laissez blondir l’ail 2 min sans qu’il brunisse.","Ajoutez la farine de riz, remuez 30 s, puis versez le vin et le fumet en remuant pour obtenir une sauce lisse. Laissez frémir 3 min.","Salez le merlu, posez-le dans la sauce avec les palourdes. Couvrez et cuisez 6 à 8 min à feu doux en secouant la sauteuse en rond : ce mouvement émulsionne la sauce. Les palourdes doivent être ouvertes et le poisson nacré.","Ajoutez asperges, petits pois, pommes de terre coupées en deux et le persil, réchauffez 2 min.","Disposez les quartiers d’œuf dur, saupoudrez de piment d’Espelette et servez dans la cassole."],"tags":["riche en protéines","une poêle","sans gluten","léger"],"seasons":["printemps"],"technique":"poche","flavors":["iode","herbace","frais"],"tips":"Pourquoi c’est nutritif : les palourdes apportent du fer et de la vitamine B12 en quantité remarquable, le merlu des protéines très digestes et l’iode de la mer."},{"id":"fb-sardines-grillees-panisses","name":"Sardines grillées, panisses dorées et salade de tomates","description":"Des sardines fraîches grillées au feu vif avec fleur de sel et citron, accompagnées de panisses marseillaises dorées à la poêle et d’une salade de tomates à l’oignon.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":25,"restTime":120,"difficulty":"facile","servings":2,"ingredients":[{"id":"sardine","qty":10,"unit":"piece","note":"fraîches, vidées"},{"id":"farine-riz","qty":120,"unit":"g","note":"farine de pois chiche"},{"id":"eau","qty":450,"unit":"ml"},{"id":"huile-olive","qty":50,"unit":"ml"},{"id":"tomate","qty":3,"unit":"piece"},{"id":"oignon-rouge","qty":0.5,"unit":"piece"},{"id":"citron","qty":1,"unit":"piece"},{"id":"origan","qty":1,"unit":"cac","note":"herbes de Provence"},{"id":"basilic","qty":6,"unit":"feuille"},{"id":"yaourt-grec","qty":150,"unit":"g","note":"en sauce, avec citron et basilic"},{"id":"sel","qty":1,"unit":"au-gout","note":"fleur de sel"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Panisses (au moins 2 h avant) : portez l’eau salée et 1 c. à soupe d’huile à ébullition. Versez la farine de pois chiche en pluie en fouettant vivement, puis cuisez 10 min à feu doux en remuant à la spatule jusqu’à une pâte épaisse qui se détache des parois.","Étalez la pâte sur 1,5 cm dans un plat huilé, lissez et laissez refroidir 2 h au réfrigérateur pour qu’elle prenne.","Coupez les tomates en quartiers, l’oignon en fines lamelles, assaisonnez de 2 c. à soupe d’huile, de sel et de basilic. Mélangez le yaourt avec un filet de citron, du sel et du basilic ciselé.","Coupez la pâte en bâtonnets. Faites-les dorer dans 2 c. à soupe d’huile d’olive dans une poêle à feu moyen-vif, 3 min par face, jusqu’à ce qu’ils soient croustillants. Égouttez sur papier.","Badigeonnez les sardines du reste d’huile, salez et parsemez d’herbes de Provence. Faites-les griller sur un gril ou une plancha très chaude 2 à 3 min par face, jusqu’à ce que la peau cloque et noircisse par endroits.","Servez aussitôt avec les panisses, la salade de tomates, la sauce au yaourt et des quartiers de citron."],"tags":["barbecue","sans gluten","riche en protéines","économique"],"seasons":["ete"],"technique":"grill","flavors":["grille","iode","frais"],"tips":"Pourquoi c’est nutritif : la sardine entière est l’un des poissons les plus riches en oméga-3 et en vitamine D, et sa petite taille limite l’accumulation de mercure. La pâte à panisse se prépare la veille."},{"id":"fb-maquereaux-sauce-moutarde-poireaux","name":"Maquereaux grillés sauce moutarde à la crème, poireaux vinaigrette","description":"Des filets de maquereau grillés côté peau, une sauce crème fraîche-moutarde à l’ancienne, un poireau tiède en vinaigrette à l’œuf mimosa et des pommes vapeur.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"maquereau","qty":2,"unit":"piece","note":"levés en filets"},{"id":"poireau","qty":1,"unit":"piece","note":"jeune et fin"},{"id":"pomme-de-terre","qty":220,"unit":"g"},{"id":"creme-fraiche","qty":80,"unit":"ml"},{"id":"moutarde","qty":2,"unit":"cas","note":"à l’ancienne"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"oeuf","qty":2,"unit":"piece","note":"durs"},{"id":"ciboulette","qty":10,"unit":"g"},{"id":"beurre","qty":15,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les œufs 10 min à l’eau bouillante, refroidissez-les et écalez-les. Cuisez les pommes de terre épluchées 20 min à la vapeur.","Coupez le poireau en tronçons de 8 cm, lavez-les et cuisez-les 12 min à la vapeur : la pointe d’un couteau doit s’y enfoncer sans résistance.","Fouettez 1 c. à soupe de moutarde, le vinaigre, l’huile, du sel et du poivre. Versez sur le poireau tiède et râpez les œufs durs par-dessus.","Dans une petite casserole à feu doux, chauffez la crème fraîche avec le reste de moutarde 2 min sans bouillir. Ajoutez la moitié de la ciboulette.","Salez les filets de maquereau, entaillez légèrement la peau. Faites chauffer le beurre dans une poêle à feu vif et posez les filets côté peau 3 min sans les bouger, jusqu’à ce que la peau soit croustillante, puis 30 s côté chair.","Servez les maquereaux nappés de sauce, avec le poireau mimosa, les pommes vapeur et le reste de ciboulette."],"tags":["rapide","économique","riche en protéines","sans gluten"],"seasons":["printemps","automne"],"technique":"poele","flavors":["iode","cremeux","acidule"],"tips":"Pourquoi c’est nutritif : le maquereau est riche en EPA et DHA (oméga-3), en vitamine D et en sélénium, et la crème fraîche lactofermentée apporte ses graisses saturées stables. Choisissez des poissons à l’œil brillant."},{"id":"fb-truite-au-bleu-beurre-capres","name":"Truite au bleu, beurre fondu aux câpres et pommes vapeur","description":"La truite pochée entière dans un court-bouillon vinaigré qui bleuit sa peau, servie avec un beurre fondu aux câpres et au citron, des pommes vapeur et des carottes.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"truite","qty":2,"unit":"piece","note":"vidées, peau intacte"},{"id":"vinaigre-cidre","qty":100,"unit":"ml"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"eau","qty":1500,"unit":"ml"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":2,"unit":"brin"},{"id":"pomme-de-terre","qty":320,"unit":"g"},{"id":"beurre","qty":60,"unit":"g"},{"id":"capres","qty":2,"unit":"cas"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"oeuf","qty":2,"unit":"piece","note":"mollets"},{"id":"aneth","qty":5,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Court-bouillon : portez à ébullition l’eau, le vin blanc, l’oignon émincé, le laurier, le thym et 1 c. à soupe de sel dans une sauteuse assez large pour les truites. Laissez frémir 15 min.","Cuisez les pommes de terre épluchées 20 min à la vapeur. Cuisez les œufs 6 min à l’eau bouillante et écalez-les.","Manipulez les truites le moins possible pour ne pas abîmer la pellicule qui bleuit. Portez le vinaigre à ébullition dans une petite casserole et arrosez-en les truites : la peau prend une teinte bleu acier.","Plongez les truites dans le court-bouillon frémissant, baissez à feu très doux (sans bouillir) et pochez 8 à 10 min : l’œil devient blanc et la nageoire dorsale se détache facilement.","Faites fondre le beurre à feu doux, ajoutez les câpres et le jus du demi-citron.","Égouttez les truites, servez-les avec les pommes vapeur, l’œuf mollet, le beurre aux câpres et l’aneth."],"tags":["rapide","léger","riche en protéines","sans gluten"],"seasons":["printemps","ete"],"technique":"poche","flavors":["acidule","frais","lacte"],"tips":"Pourquoi c’est nutritif : la truite apporte des oméga-3, de la vitamine D et du sélénium, et le pochage doux préserve ses graisses fragiles. Le court-bouillon filtré sert de base pour une soupe."},{"id":"fb-daube-thon-olives-polenta","name":"Thon en daube à la provençale, olives et câpres, polenta grillée","description":"Une belle tranche de thon piquée d’ail et d’anchois, braisée doucement dans le vin blanc, les tomates et les olives, servie avec des tranches de polenta grillées.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":45,"restTime":120,"difficulty":"facile","servings":2,"ingredients":[{"id":"thon","qty":400,"unit":"g","note":"une tranche épaisse de 4 cm"},{"id":"anchois","qty":4,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"vin-blanc","qty":100,"unit":"ml"},{"id":"olive","qty":50,"unit":"g","note":"noires de Nice"},{"id":"capres","qty":1,"unit":"cas"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"origan","qty":1,"unit":"cac"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"polenta","qty":140,"unit":"g"},{"id":"eau","qty":600,"unit":"ml"},{"id":"parmesan","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Polenta (2 h avant ou la veille) : portez l’eau salée à ébullition, versez la polenta en pluie en fouettant et cuisez 10 min à feu doux en remuant. Ajoutez le parmesan, étalez sur 2 cm dans un plat huilé et laissez prendre au réfrigérateur.","Piquez la tranche de thon avec la pointe d’un couteau et glissez dans les incisions des morceaux d’anchois et des éclats d’ail. Salez peu, poivrez.","Dans une sauteuse, faites chauffer 2 c. à soupe d’huile à feu vif et saisissez le thon 2 min par face pour le colorer. Réservez.","À feu moyen, faites fondre l’oignon émincé 5 min, ajoutez le reste d’ail, déglacez au vin blanc, puis ajoutez les tomates, l’origan et le laurier. Laissez compoter 15 min à découvert.","Remettez le thon dans la sauce avec les olives et les câpres, couvrez et braisez 12 min à feu très doux en le retournant à mi-cuisson : il doit rester légèrement rosé au centre.","Coupez la polenta en tranches, badigeonnez-les du reste d’huile et faites-les griller 3 min par face dans une poêle-gril très chaude. Servez avec le thon nappé de sauce."],"tags":["riche en protéines","sans gluten","préparation à l’avance"],"seasons":["ete","automne"],"technique":"braise","flavors":["umami","herbace","acidule"],"tips":"Pourquoi c’est nutritif : le thon frais apporte protéines, oméga-3 et vitamine D, l’huile d’olive et les olives des polyphénols. Limitez le thon rouge à une fois par semaine (mercure) ; la bonite convient très bien."},{"id":"fb-raito-morue-riz","name":"Raïto de morue au vin rouge, olives et câpres, riz pilaf","description":"Le plat du réveillon provençal : morue dessalée poêlée puis mijotée dans une sauce au vin rouge, tomates, olives noires, câpres et noix, avec un riz pilaf au laurier.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":45,"restTime":1440,"difficulty":"facile","servings":2,"ingredients":[{"id":"morue-salee","qty":240,"unit":"g","note":"en morceaux épais"},{"id":"vin-rouge","qty":200,"unit":"ml"},{"id":"tomates-concassees","qty":300,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"olive","qty":50,"unit":"g","note":"noires"},{"id":"capres","qty":1,"unit":"cas"},{"id":"noix","qty":20,"unit":"g","note":"cerneaux concassés"},{"id":"huile-olive","qty":40,"unit":"ml"},{"id":"farine-riz","qty":1,"unit":"cas"},{"id":"thym","qty":2,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"riz-blanc","qty":130,"unit":"g"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : dessalez la morue 24 h dans un grand volume d’eau froide, au réfrigérateur, en changeant l’eau 3 ou 4 fois. Égouttez et épongez.","Sauce : faites fondre l’oignon haché dans 2 c. à soupe d’huile 8 min à feu moyen, ajoutez l’ail écrasé, puis le vin rouge. Faites réduire de moitié (5 min), ajoutez les tomates, le thym et 1 feuille de laurier, et laissez mijoter 20 min à feu doux.","Riz pilaf : nacrez le riz dans 1 c. à soupe d’huile 2 min, versez le bouillon chaud et la seconde feuille de laurier, couvrez et cuisez 12 min à feu doux. Laissez reposer 5 min hors du feu.","Passez les morceaux de morue dans la farine de riz et faites-les dorer dans le reste d’huile à feu moyen-vif, 2 min par face.","Ajoutez dans la sauce les olives, les câpres et les noix, puis glissez la morue. Laissez mijoter 8 min à feu très doux : la chair doit se détacher en lamelles nacrées. Poivrez, ne salez pas.","Servez la raïto bien chaude avec le riz pilaf."],"tags":["préparation à l’avance","riche en protéines","sans gluten","réconfortant"],"seasons":["hiver"],"technique":"mijote","flavors":["umami","acidule","reconfortant"],"tips":"Pourquoi c’est nutritif : la morue est un poisson maigre très riche en protéines et en iode, et les noix ajoutent quelques oméga-3 végétaux. Respectez le dessalage pour que le plat ne soit pas trop salé."},{"id":"fb-seiches-rouille-setoise","name":"Rouille de seiches à la sétoise, pommes de terre fondantes","description":"Des seiches mijotées longuement dans une sauce tomate au vin blanc et au safran, liée en fin de cuisson par une rouille à l’ail et au jaune d’œuf, avec des pommes de terre qui cuisent dans la sauce.","emoji":"🦑","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":90,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"calamar","qty":1400,"unit":"g","note":"seiches nettoyées, en lanières"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"fumet-poisson","qty":300,"unit":"ml"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"ail","qty":6,"unit":"gousse"},{"id":"safran","qty":2,"unit":"pincee"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"pomme-de-terre","qty":700,"unit":"g"},{"id":"jaune-oeuf","qty":2,"unit":"piece"},{"id":"huile-olive","qty":120,"unit":"ml"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"graines-fenouil","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez les lanières de seiche. Dans une grande cocotte, chauffez 3 c. à soupe d’huile à feu vif et faites-les revenir 8 min en remuant, jusqu’à ce que leur eau soit évaporée.","Ajoutez les oignons émincés et 3 gousses d’ail hachées, faites suer 5 min à feu moyen. Versez le vin blanc, laissez réduire 3 min, puis ajoutez tomates, fumet, safran, piment, fenouil et laurier.","Couvrez et laissez mijoter 50 min à feu doux : la seiche doit devenir tendre sous la dent.","Ajoutez les pommes de terre coupées en gros cubes et poursuivez 25 min à couvert.","Rouille : écrasez les 3 gousses d’ail restantes avec une pincée de sel, ajoutez les jaunes d’œuf et 1 c. à soupe de sauce chaude, puis montez au fouet en versant le reste d’huile en filet, comme une mayonnaise.","Hors du feu, prélevez une louche de sauce, mélangez-la à la rouille, puis reversez le tout dans la cocotte en remuant doucement sans refaire bouillir. Servez aussitôt."],"tags":["mijoté","week-end","riche en protéines","sans gluten","familial"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["iode","epice","umami"],"tips":"Pourquoi c’est nutritif : la seiche est très riche en protéines maigres, en B12 et en sélénium, et les jaunes d’œuf crus de la rouille apportent choline et vitamines liposolubles. Les calamars ou encornets conviennent aussi."},{"id":"fb-grenouilles-dombes-persillade","name":"Cuisses de grenouilles de la Dombes en persillade, riz crémeux au comté","description":"Des cuisses de grenouilles sautées au beurre mousseux, à l’ail et au persil comme dans les auberges de la Dombes, avec un riz crémeux au comté et à la crème.","emoji":"🐸","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":25,"difficulty":"facile","servings":2,"ingredients":[{"id":"escargots","qty":500,"unit":"g","note":"cuisses de grenouilles fraîches ou décongelées"},{"id":"lait","qty":150,"unit":"ml","note":"pour les tremper"},{"id":"farine-riz","qty":2,"unit":"cas"},{"id":"beurre","qty":35,"unit":"g"},{"id":"beurre-clarifie","qty":1,"unit":"cas"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"persil","qty":10,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"riz-rond","qty":150,"unit":"g"},{"id":"bouillon-volaille","qty":450,"unit":"ml"},{"id":"comte","qty":35,"unit":"g","note":"râpé"},{"id":"creme-fraiche","qty":40,"unit":"ml"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites tremper les cuisses de grenouilles 20 min dans le lait froid, égouttez-les, épongez-les et passez-les dans la farine de riz en tapotant pour ne garder qu’un voile.","Riz : faites suer l’échalote ciselée 2 min dans 10 g de beurre, ajoutez le riz et nacrez-le 1 min. Mouillez avec le bouillon chaud louche par louche pendant 18 min à feu moyen, en remuant. Hors du feu, ajoutez le comté et la crème.","Hachez finement l’ail et le persil ensemble.","Dans une grande poêle, faites chauffer le beurre clarifié et 20 g de beurre à feu moyen-vif jusqu’à ce qu’il mousse. Saisissez les cuisses en une seule couche 4 à 5 min, en les retournant, jusqu’à ce qu’elles soient dorées.","Ajoutez le reste du beurre et la persillade, faites sauter 1 min sans laisser brûler l’ail. Arrosez de jus de citron, salez et poivrez.","Servez aussitôt les grenouilles avec leur beurre persillé, à côté du riz crémeux."],"tags":["rapide","une poêle","sans gluten","week-end"],"seasons":["printemps"],"technique":"poele","flavors":["herbace","lacte","cremeux"],"tips":"Pourquoi c’est nutritif : la chair de grenouille est une protéine maigre et très digeste, et le comté affiné apporte calcium et vitamine K2. On les mange avec les doigts, comme dans la Dombes."},{"id":"fb-lapin-gibelotte","name":"Lapin en gibelotte au vin blanc, lardons et petits oignons","description":"Le ragoût de lapin des guinguettes : morceaux de lapin dorés au saindoux, mijotés au vin blanc et au bouillon avec lardons, champignons, petits oignons et pommes de terre.","emoji":"🐇","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":80,"difficulty":"facile","servings":4,"ingredients":[{"id":"lapin","qty":1600,"unit":"g","note":"un lapin découpé, avec le foie"},{"id":"lardons","qty":180,"unit":"g"},{"id":"oignon","qty":12,"unit":"piece","note":"petits oignons grelots (environ 300 g)"},{"id":"champignon","qty":250,"unit":"g"},{"id":"vin-blanc","qty":400,"unit":"ml"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"pomme-de-terre","qty":700,"unit":"g"},{"id":"graisse-canard","qty":2,"unit":"cas","note":"saindoux"},{"id":"farine-riz","qty":1,"unit":"cas"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une cocotte, faites revenir les lardons à sec 5 min à feu moyen, puis les petits oignons épluchés 5 min. Réservez-les avec une écumoire.","Ajoutez la graisse et faites dorer les morceaux de lapin à feu moyen-vif, 8 min en les retournant, jusqu’à ce qu’ils soient blonds sur toutes les faces. Saupoudrez de farine de riz et remuez 1 min.","Versez le vin blanc en grattant le fond, laissez bouillir 2 min, puis ajoutez le bouillon, l’ail écrasé, le thym et le laurier. Couvrez et laissez mijoter 30 min à feu doux.","Ajoutez les pommes de terre en gros morceaux, les lardons, les oignons et les champignons coupés en quatre. Poursuivez 35 min à couvert : la viande doit se détacher facilement de l’os.","Hachez le foie du lapin et le persil, ajoutez-les dans la sauce 3 min avant la fin : il épaissit et parfume la sauce.","Rectifiez l’assaisonnement et servez directement dans la cocotte."],"tags":["mijoté","familial","réconfortant","week-end","économique"],"seasons":["printemps","automne"],"technique":"mijote","flavors":["reconfortant","umami"],"tips":"Pourquoi c’est nutritif : le lapin est une viande maigre et riche en vitamine B12, cuite sur l’os ; son foie ajouté à la sauce apporte fer et vitamine A. Se réchauffe très bien."},{"id":"fb-pintade-raisins-verjus-panais","name":"Pintade rôtie au verjus et aux raisins, panais rôtis au beurre","description":"Une pintade fermière rôtie sur un lit de raisins, déglacée au verjus et au bouillon pour une sauce aigre-douce, avec des panais rôtis au beurre et au thym.","emoji":"🍇","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":75,"difficulty":"facile","servings":4,"ingredients":[{"id":"pintade","qty":1,"unit":"piece","note":"fermière, environ 1,4 kg"},{"id":"raisin","qty":400,"unit":"g","note":"muscat ou chasselas"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"verjus si possible"},{"id":"bouillon-volaille","qty":250,"unit":"ml"},{"id":"panais","qty":900,"unit":"g"},{"id":"pomme-de-terre","qty":400,"unit":"g"},{"id":"beurre","qty":80,"unit":"g"},{"id":"foie-volaille","qty":150,"unit":"g","note":"pour la farce"},{"id":"jambon-cru","qty":4,"unit":"piece","note":"tranches fines"},{"id":"thym","qty":4,"unit":"brin"},{"id":"echalote","qty":2,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 200 °C. Hachez grossièrement les foies avec une échalote, sel et poivre, et glissez ce mélange dans la pintade. Bridez-la, enduisez-la de 30 g de beurre mou, salez et couvrez les filets avec le jambon cru.","Coupez les panais en bâtonnets et les pommes de terre en quartiers, enrobez-les de 30 g de beurre fondu, de thym et de sel, et étalez-les sur une plaque.","Posez la pintade dans un plat sur la moitié du raisin et l’autre échalote émincée. Enfournez la pintade et les légumes 1 h 10, en arrosant la volaille toutes les 20 min et en retournant les légumes à mi-cuisson. Le jus doit couler clair quand on pique la cuisse.","Laissez reposer la pintade 10 min sous une feuille d’aluminium.","Posez le plat sur feu moyen, déglacez au verjus, ajoutez le bouillon et le reste du raisin et réduisez 5 min. Montez la sauce avec le reste de beurre.","Découpez la pintade, servez avec la farce aux foies, les légumes rôtis et la sauce aux raisins."],"tags":["four","week-end","familial","abats","sans gluten"],"seasons":["automne"],"technique":"roti","flavors":["fruite","acidule","grille"],"tips":"Pourquoi c’est nutritif : la pintade a une chair plus riche en fer que le poulet, la farce aux foies glisse un abat sans qu’on le remarque, et le panais apporte une énergie douce et sans oxalates."},{"id":"fb-confit-canard-cepes-persillade","name":"Confit de canard, cèpes en persillade et pommes de terre à la graisse","description":"Des cuisses confites au four jusqu’à la peau craquante, des cèpes sautés à l’ail et au persil et des pommes de terre rissolées dans la graisse de confit, avec une salade de mâche aux noix.","emoji":"🦆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":40,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"canard-cuisse","qty":2,"unit":"piece","note":"confites"},{"id":"champignon-forestier","qty":300,"unit":"g","note":"cèpes"},{"id":"pomme-de-terre","qty":320,"unit":"g"},{"id":"graisse-canard","qty":2,"unit":"cas","note":"celle du confit"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"persil","qty":5,"unit":"g"},{"id":"mache","qty":80,"unit":"g"},{"id":"noix","qty":14,"unit":"g"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"huile-olive","qty":15,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 200 °C. Grattez l’excès de graisse des cuisses et posez-les côté peau vers le haut dans un plat. Enfournez 25 min, jusqu’à ce que la peau soit croustillante et dorée.","Coupez les pommes de terre en rondelles de 5 mm et faites-les rissoler dans 1 c. à soupe de graisse de canard à feu moyen, 20 min, en les retournant, jusqu’à ce qu’elles soient dorées et fondantes. Salez.","Nettoyez les cèpes au pinceau et coupez-les en tranches. Dans une poêle très chaude, faites-les sauter dans le reste de graisse 6 min sans trop remuer, jusqu’à ce qu’ils soient dorés.","Hachez l’ail et le persil, ajoutez-les aux cèpes, faites sauter 1 min hors du feu fort. Salez et poivrez.","Assaisonnez la mâche avec le vinaigre, l’huile d’olive et les noix concassées.","Servez les cuisses confites sur les pommes de terre, avec les cèpes et la salade."],"tags":["rapide","calorique","prise de masse","sans gluten","réconfortant"],"seasons":["automne"],"technique":"four","flavors":["umami","grille","reconfortant"],"tips":"Pourquoi c’est nutritif : la graisse de canard est riche en acides gras mono-insaturés, stables à la cuisson, et la peau confite apporte du collagène. Hors saison, des cèpes séchés réhydratés font l’affaire."},{"id":"fb-poulet-ecrevisses-lyonnais","name":"Poulet aux écrevisses à la lyonnaise, riz pilaf","description":"Le grand classique des mères lyonnaises : cuisses de poulet sautées puis mijotées avec des écrevisses dans une sauce au vin blanc, à la tomate et à la crème, avec un riz pilaf.","emoji":"🦞","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":50,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece","note":"coupées en deux à la jointure"},{"id":"langoustine","qty":16,"unit":"piece","note":"écrevisses vivantes ou surgelées entières"},{"id":"beurre","qty":50,"unit":"g"},{"id":"echalote","qty":3,"unit":"piece"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-blanc","qty":250,"unit":"ml"},{"id":"vin-rouge","qty":30,"unit":"ml","note":"cognac"},{"id":"concentre-tomate","qty":2,"unit":"cas"},{"id":"tomate","qty":2,"unit":"piece"},{"id":"creme-fraiche","qty":200,"unit":"ml"},{"id":"estragon","qty":3,"unit":"brin"},{"id":"riz-blanc","qty":280,"unit":"g"},{"id":"bouillon-volaille","qty":550,"unit":"ml"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une sauteuse, faites dorer les morceaux de poulet dans 30 g de beurre à feu moyen-vif, 10 min côté peau puis 5 min de l’autre côté. Réservez.","Dans la même graisse à feu vif, faites sauter les écrevisses 3 min, jusqu’à ce qu’elles soient bien rouges. Arrosez de cognac. Retirez-les, décortiquez les queues et réservez-les ; remettez les carcasses dans la sauteuse et écrasez-les au pilon.","Ajoutez échalotes et ail hachés, le concentré et les tomates en dés, remuez 2 min. Versez le vin blanc, remettez le poulet, couvrez et laissez mijoter 30 min à feu doux.","Riz pilaf : nacrez le riz 2 min dans le reste de beurre, mouillez avec 500 ml de bouillon chaud, couvrez et cuisez 12 min à feu doux.","Retirez le poulet, passez la sauce au chinois en pressant bien les carcasses. Remettez-la sur le feu avec la crème, l’estragon et le piment, et réduisez 5 min jusqu’à ce qu’elle nappe la cuillère.","Remettez le poulet et les queues d’écrevisses dans la sauce 2 min pour les réchauffer, puis servez avec le riz."],"tags":["week-end","riche en protéines","sans gluten","familial"],"seasons":["ete"],"technique":"braise","flavors":["iode","cremeux","umami"],"tips":"Pourquoi c’est nutritif : la cuisse de poulet avec sa peau est plus riche en fer et en zinc que le blanc, et les carcasses d’écrevisses écrasées donnent à la sauce minéraux et caroténoïdes. Des langoustines ou des crevettes entières remplacent les écrevisses."},{"id":"fb-poulet-quarante-gousses-butternut","name":"Poulet aux quarante gousses d’ail, courge butternut rôtie","description":"Des cuisses de poulet cuites en cocotte lutée avec quarante gousses d’ail en chemise, thym et romarin. L’ail devient une crème douce à tartiner sur des tranches de butternut rôtie.","emoji":"🧄","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":80,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":5,"unit":"piece","note":"avec la peau"},{"id":"ail","qty":40,"unit":"gousse","note":"en chemise (3 têtes)"},{"id":"huile-olive","qty":60,"unit":"ml"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"thym","qty":5,"unit":"brin"},{"id":"romarin","qty":2,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"courge-butternut","qty":1200,"unit":"g"},{"id":"pomme-de-terre","qty":400,"unit":"g"},{"id":"beurre","qty":30,"unit":"g"},{"id":"yaourt-grec","qty":200,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 180 °C. Salez et poivrez les cuisses. Dans une cocotte en fonte, faites-les dorer côté peau dans 2 c. à soupe d’huile, 8 min à feu moyen-vif.","Ajoutez les gousses d’ail non épluchées, les herbes, le vin blanc et le reste d’huile. Fermez la cocotte hermétiquement en glissant une feuille de papier aluminium sous le couvercle et enfournez 1 h 15.","Coupez la butternut en tranches épaisses (peau comprise) et les pommes de terre en quartiers, enrobez-les de beurre fondu et de sel et rôtissez-les sur une plaque dans le même four 45 min, en les retournant à mi-cuisson.","Sortez la cocotte : les cuisses doivent être confites et l’ail fondant. Retirez le couvercle et passez la cocotte 10 min sous le gril pour recroustiller la peau.","Mélangez le yaourt avec 3 gousses d’ail pressées hors de leur peau et une pincée de sel.","Servez le poulet avec les légumes rôtis : chacun presse ses gousses d’ail pour les étaler sur la courge, avec le yaourt à l’ail."],"tags":["four","familial","réconfortant","sans gluten","riche en protéines"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","herbace"],"tips":"Pourquoi c’est nutritif : l’ail longuement confit garde ses composés soufrés et devient très digeste, la courge apporte bêta-carotène et le yaourt grec des ferments vivants."},{"id":"fb-tendrons-veau-feves-navets","name":"Tendrons de veau braisés aux fèves, navets nouveaux et sarriette","description":"Des tendrons de veau dorés puis braisés au vin blanc jusqu’à ce que leurs cartilages fondent, avec des fèves fraîches, des navets nouveaux glacés, des oignons nouveaux et des pommes de terre nouvelles.","emoji":"🫛","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"veau-epaule","qty":1200,"unit":"g","note":"tendrons de veau, en morceaux de 6 cm"},{"id":"lardons","qty":150,"unit":"g"},{"id":"feves","qty":400,"unit":"g","note":"écossées et dérobées"},{"id":"navet","qty":6,"unit":"piece","note":"navets nouveaux"},{"id":"oignon-nouveau","qty":8,"unit":"piece"},{"id":"pomme-de-terre","qty":700,"unit":"g","note":"nouvelles"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-volaille","qty":400,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"origan","qty":2,"unit":"brin","note":"sarriette fraîche"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez les tendrons et salez-les. Dans une cocotte, faites-les dorer dans 20 g de beurre à feu moyen-vif, 10 min, en plusieurs fois pour ne pas les entasser. Réservez.","Faites revenir les lardons 4 min, puis les oignons nouveaux coupés en deux 3 min. Déglacez au vin blanc, grattez les sucs et laissez réduire 2 min.","Remettez les tendrons, mouillez avec le bouillon, ajoutez le thym. Couvrez et laissez mijoter 1 h 15 à feu doux : les cartilages doivent devenir moelleux.","Ajoutez les pommes de terre nouvelles et les navets coupés en deux, et poursuivez 20 min.","Ajoutez les fèves et la sarriette, couvrez et cuisez encore 6 min : les fèves doivent rester d’un vert vif et fondantes.","Hors du feu, incorporez le reste du beurre en remuant doucement pour lustrer les légumes. Rectifiez l’assaisonnement et servez."],"tags":["mijoté","riche en collagène","familial","week-end"],"seasons":["printemps"],"technique":"braise","flavors":["frais","reconfortant","herbace"],"tips":"Pourquoi c’est nutritif : le tendron, morceau de poitrine avec cartilages, libère beaucoup de gélatine en cuisant ; les fèves apportent fibres, folates et fer végétal, les navets nouveaux de la vitamine C. Des fèves surgelées conviennent hors saison."},{"id":"fb-souris-agneau-miel-puree-panais","name":"Souris d’agneau confites au miel et au romarin, purée de panais à l’ail","description":"Des souris d’agneau confites quatre heures au four avec ail, romarin, vin blanc et une touche de miel, jusqu’à tomber de l’os, servies sur une purée de panais à l’ail confit.","emoji":"🐑","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":240,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"agneau-souris","qty":4,"unit":"piece"},{"id":"ail","qty":12,"unit":"gousse"},{"id":"romarin","qty":3,"unit":"brin"},{"id":"thym","qty":3,"unit":"brin"},{"id":"miel","qty":2,"unit":"cas"},{"id":"vin-blanc","qty":250,"unit":"ml"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"panais","qty":1000,"unit":"g"},{"id":"beurre","qty":50,"unit":"g"},{"id":"creme-fraiche","qty":80,"unit":"ml"},{"id":"huile-olive","qty":30,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 150 °C. Salez les souris et faites-les dorer dans l’huile d’olive dans une cocotte à feu vif, 8 min en les tournant.","Ajoutez les oignons en quartiers, les gousses d’ail en chemise, le romarin et le thym. Versez le vin blanc et le bouillon, arrosez de miel.","Couvrez et enfournez 3 h 30, en arrosant les souris de leur jus toutes les heures. Elles sont prêtes quand l’os se retire sans effort.","Retirez le couvercle, montez le four à 200 °C et laissez caraméliser 20 min en arrosant deux fois.","Cuisez les panais épluchés et coupés en morceaux 20 min à l’eau salée. Pressez 6 gousses d’ail confites de la cocotte et mixez-les avec les panais, le beurre et la crème jusqu’à une purée lisse.","Filtrez le jus de cuisson et dégraissez-le. Servez chaque souris sur la purée, nappée de jus."],"tags":["mijoté","week-end","four","riche en collagène","prise de masse","sans gluten"],"seasons":["hiver","printemps"],"technique":"braise","flavors":["reconfortant","herbace","sucre"],"tips":"Pourquoi c’est nutritif : la souris, morceau de jarret d’agneau, est riche en tissu conjonctif qui donne une sauce collante et nourrissante, et l’agneau est l’une des viandes les plus riches en zinc et en B12."},{"id":"fb-gardiane-taureau-riz-camargue","name":"Gardiane de taureau aux olives noires, riz de Camargue","description":"Le ragoût des gardians : bœuf (ou taureau AOP) mariné une nuit au vin rouge et aux aromates, mijoté avec olives noires et zeste d’orange, servi sur du riz de Camargue.","emoji":"🐂","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":180,"restTime":720,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-paleron","qty":900,"unit":"g","note":"taureau de Camargue ou paleron, en gros cubes"},{"id":"vin-rouge","qty":600,"unit":"ml","note":"vin de sable ou costières"},{"id":"oignon","qty":3,"unit":"piece"},{"id":"ail","qty":5,"unit":"gousse"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"orange","qty":1,"unit":"piece","note":"le zeste en rubans"},{"id":"olive","qty":120,"unit":"g","note":"noires, dénoyautées"},{"id":"anchois","qty":4,"unit":"piece"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"girofle","qty":2,"unit":"pincee","note":"2 clous"},{"id":"huile-olive","qty":35,"unit":"ml"},{"id":"riz-blanc","qty":260,"unit":"g","note":"riz long de Camargue"},{"id":"beurre","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : mettez la viande dans un saladier avec le vin, 1 oignon émincé, l’ail écrasé, la carotte en rondelles, le zeste d’orange, le thym, le laurier et le girofle. Couvrez et laissez mariner 12 h (une nuit) au réfrigérateur.","Égouttez la viande en conservant la marinade, épongez-la bien. Dans une cocotte, faites-la dorer dans l’huile d’olive à feu vif, en plusieurs fois, 3 min par fournée.","Ajoutez les 2 oignons restants émincés et faites-les fondre 5 min à feu moyen. Versez la marinade avec ses aromates, portez à ébullition et écumez.","Couvrez et laissez mijoter 2 h 30 à feu très doux, jusqu’à ce que la viande se coupe à la cuillère.","Écrasez les anchois dans un peu de sauce, ajoutez-les avec les olives et laissez mijoter 20 min à découvert pour que la sauce réduise et devienne brillante.","Cuisez le riz 12 min à l’eau bouillante salée, égouttez-le et mélangez-le au beurre. Servez la gardiane sur le riz."],"tags":["mijoté","préparation à l’avance","batch cooking","réconfortant","sans gluten"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","fruite","reconfortant"],"tips":"Pourquoi c’est nutritif : le paleron, morceau gélatineux, cuit longuement dans le vin devient très digeste et apporte fer et zinc ; les olives et l’huile d’olive ajoutent des polyphénols. Meilleure encore réchauffée le lendemain."},{"id":"fb-boeuf-ficelle-sauce-raifort","name":"Bœuf à la ficelle, légumes du bouillon et sauce au raifort","description":"Un rôti de bœuf suspendu à une ficelle et poché quelques minutes dans un bouillon d’os bien parfumé : rosé à cœur, servi avec navets, poireaux, pommes de terre et une crème au raifort.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":45,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"boeuf-rosbif","qty":900,"unit":"g","note":"filet ou tende de tranche, ficelé"},{"id":"bouillon-boeuf","qty":2000,"unit":"ml","note":"bouillon d’os maison"},{"id":"os-a-moelle","qty":4,"unit":"piece"},{"id":"navet","qty":6,"unit":"piece"},{"id":"poireau","qty":1,"unit":"piece"},{"id":"pomme-de-terre","qty":600,"unit":"g"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"raifort","qty":2,"unit":"cas","note":"râpé"},{"id":"cornichon","qty":60,"unit":"g"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout","note":"gros sel"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Sortez la viande du réfrigérateur 1 h avant. Nouez une longue ficelle au rôti pour pouvoir le suspendre à une cuillère en bois posée sur la marmite.","Portez le bouillon à ébullition avec le thym et le laurier. Ajoutez les pommes de terre, les navets coupés en deux et le poireau en tronçons, et cuisez 20 min à petits frémissements.","Ajoutez les os à moelle (bouts salés au gros sel pour garder la moelle) et poursuivez 10 min.","Plongez le rôti suspendu dans le bouillon frémissant, sans qu’il touche le fond : comptez 12 à 15 min pour 900 g (environ 15 min par kilo) pour une cuisson rosée, 55 °C à cœur.","Mélangez la crème fraîche, le raifort, une pincée de sel et du poivre.","Laissez reposer la viande 5 min, tranchez-la et servez-la dans des assiettes creuses avec les légumes, la moelle, une louche de bouillon, la sauce au raifort, du gros sel et les cornichons."],"tags":["riche en protéines","week-end","familial","riche en collagène","sans gluten","fermenté"],"seasons":["hiver"],"technique":"poche","flavors":["umami","piquant","frais"],"tips":"Pourquoi c’est nutritif : le bouillon d’os et la moelle apportent gélatine, glycine et graisses nourrissantes, et le pochage doux préserve la tendreté de la viande. Le bouillon restant fait une soupe le lendemain."},{"id":"fb-travers-porc-confits-grenailles","name":"Travers de porc confits à l’ail et au thym, grenailles et salade de chou","description":"Des travers frottés à l’ail, au thym et au piment d’Espelette, confits doucement au four puis laqués au miel et au vinaigre de cidre, avec des grenailles rôties et une salade de chou au yaourt.","emoji":"🍖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":150,"restTime":60,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"porc-travers","qty":1300,"unit":"g"},{"id":"ail","qty":6,"unit":"gousse"},{"id":"thym","qty":4,"unit":"brin"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"miel","qty":2,"unit":"cas"},{"id":"vinaigre-cidre","qty":3,"unit":"cas"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"pomme-de-terre","qty":700,"unit":"g","note":"grenailles"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"chou-vert","qty":400,"unit":"g","note":"chou pointu, finement émincé"},{"id":"yaourt-nature","qty":2,"unit":"piece"},{"id":"pomme","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Frottez les travers avec l’ail écrasé, le thym effeuillé, le piment et 2 c. à café de sel. Laissez reposer 1 h à température ambiante (ou une nuit au réfrigérateur).","Faites chauffer le four à 150 °C. Posez les travers dans un plat, ajoutez 100 ml d’eau, couvrez hermétiquement de papier aluminium et enfournez 1 h 45.","Mélangez le miel, le vinaigre et la moutarde. Coupez les grenailles en deux et enrobez-les de graisse de canard et de sel.","Retirez l’aluminium, montez le four à 210 °C. Badigeonnez les travers de laque et glissez les grenailles sur une seconde plaque. Faites rôtir 30 min, en laquant les travers deux fois et en retournant les pommes de terre : la viande doit être brillante et caramélisée sur les bords.","Mélangez le chou émincé avec la pomme râpée, les yaourts, une pincée de sel et un trait de vinaigre.","Découpez les travers entre les os et servez avec les grenailles et la salade de chou."],"tags":["four","familial","week-end","calorique","prise de masse","sans gluten"],"seasons":["ete","automne"],"technique":"four","flavors":["sucre","grille","acidule"],"tips":"Pourquoi c’est nutritif : la viande cuite sur l’os garde ses minéraux et son collagène ; le chou cru et le yaourt apportent vitamine C et ferments. Les travers se terminent aussi très bien au barbecue."},{"id":"fb-saucisses-toulouse-chou-chataignes","name":"Saucisses de Toulouse braisées au chou vert et aux châtaignes","description":"Un plat d’hiver du Sud-Ouest : saucisses de Toulouse dorées puis braisées au bouillon avec du chou vert, des châtaignes et un peu de lard, pour une cocotte fondante.","emoji":"🌰","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":50,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saucisse-toulouse","qty":3,"unit":"piece"},{"id":"chou-vert","qty":500,"unit":"g","note":"chou frisé"},{"id":"chataigne","qty":170,"unit":"g","note":"cuites, sous vide ou au naturel"},{"id":"lardons","qty":40,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"bouillon-volaille","qty":250,"unit":"ml"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"graines-fenouil","qty":1,"unit":"pincee","note":"carvi"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"oeuf","qty":2,"unit":"piece","note":"pochés"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez le chou en lanières en retirant les grosses côtes, et blanchissez-le 4 min à l’eau bouillante salée. Égouttez.","Dans une cocotte, faites dorer les saucisses piquées dans la graisse de canard à feu moyen, 8 min en les tournant. Réservez-les.","Faites revenir les lardons et l’oignon émincé 5 min dans la cocotte. Ajoutez le chou, le carvi et mélangez pour l’enrober de gras.","Versez le bouillon, posez les saucisses par-dessus, couvrez et laissez braiser 25 min à feu doux.","Ajoutez les châtaignes, mélangez délicatement et poursuivez 10 min à couvert, jusqu’à ce qu’elles soient chaudes et que le chou soit fondant. Arrosez de vinaigre.","Pochez les œufs 3 min dans une eau frémissante vinaigrée. Servez la cocotte avec un œuf poché sur chaque assiette."],"tags":["réconfortant","économique","familial","sans gluten"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","umami"],"tips":"Pourquoi c’est nutritif : la châtaigne est un féculent sans gluten et pauvre en oxalates, le chou apporte vitamine C et K, et l’œuf poché complète l’apport en protéines et en choline."},{"id":"fb-civet-chevreuil-airelles","name":"Civet de chevreuil aux airelles, purée de céleri et panais","description":"Du chevreuil mariné une nuit au vin rouge et au genièvre, mijoté avec lardons et champignons, la sauce relevée d’airelles, avec une purée douce de céleri-rave et de panais.","emoji":"🦌","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":35,"cookTime":150,"restTime":720,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"gibier","qty":1200,"unit":"g","note":"épaule de chevreuil en cubes"},{"id":"vin-rouge","qty":600,"unit":"ml","note":"corsé"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"girofle","qty":2,"unit":"pincee","note":"2 clous"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"baies de genièvre"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"lardons","qty":100,"unit":"g"},{"id":"champignon","qty":250,"unit":"g"},{"id":"airelles","qty":80,"unit":"g"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"farine-riz","qty":1,"unit":"cas"},{"id":"celeri-rave","qty":400,"unit":"g"},{"id":"panais","qty":500,"unit":"g"},{"id":"beurre","qty":30,"unit":"g"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : faites mariner la viande 12 h (une nuit) au réfrigérateur avec le vin, 1 oignon émincé, la carotte, l’ail, le girofle, le genièvre légèrement écrasé, le laurier et le thym.","Égouttez la viande en conservant la marinade et épongez-la. Dans une cocotte, faites revenir les lardons 5 min, retirez-les, puis dorez la viande dans leur graisse à feu vif en deux fois, 4 min par fournée.","Ajoutez l’autre oignon haché, saupoudrez de farine de riz et remuez 1 min. Versez la marinade filtrée et le bouillon, portez à ébullition en grattant le fond, et écumez.","Couvrez et laissez mijoter 2 h à feu très doux. Ajoutez les lardons et les champignons coupés en quatre pour les 30 dernières minutes, puis les airelles 5 min avant la fin.","Cuisez céleri-rave et panais épluchés en morceaux 20 min à l’eau salée, égouttez et mixez avec le beurre et la crème.","Rectifiez l’assaisonnement du civet (la sauce doit napper la cuillère) et servez avec la purée."],"tags":["mijoté","week-end","préparation à l’avance","sans gluten","réconfortant"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","fruite","reconfortant"],"tips":"Pourquoi c’est nutritif : le gibier sauvage est une viande maigre, riche en fer et au profil d’acides gras plus favorable que l’élevage ; les airelles apportent des polyphénols. Le sanglier convient aussi (cuisson 2 h 30)."},{"id":"fb-potjevleesch-pommes-four","name":"Potjevleesch flamand en gelée, pommes de terre rôties et salade","description":"La terrine froide des Flandres : lapin, cuisses de poulet et veau cuits au vin blanc et au vinaigre avec un pied de veau qui fait prendre la gelée naturellement. Servie avec des pommes de terre rôties chaudes.","emoji":"🫙","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":40,"cookTime":180,"restTime":720,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"lapin","qty":800,"unit":"g","note":"en morceaux"},{"id":"poulet-cuisse","qty":3,"unit":"piece"},{"id":"veau-epaule","qty":600,"unit":"g"},{"id":"pied-veau","qty":400,"unit":"g","note":"fendu"},{"id":"vin-blanc","qty":500,"unit":"ml"},{"id":"vinaigre-cidre","qty":80,"unit":"ml"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":3,"unit":"feuille"},{"id":"girofle","qty":3,"unit":"pincee","note":"3 clous"},{"id":"pomme-de-terre","qty":1100,"unit":"g"},{"id":"graisse-canard","qty":3,"unit":"cas"},{"id":"laitue","qty":1,"unit":"piece"},{"id":"cornichon","qty":100,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : dans une cocotte, déposez le pied de veau, puis en couches le lapin, les cuisses de poulet et le veau en morceaux, en intercalant les oignons émincés, l’ail, le thym, le laurier et le girofle. Salez et poivrez chaque couche.","Versez le vin blanc et le vinaigre, complétez d’eau à hauteur. Couvrez et cuisez au four à 160 °C pendant 3 h : les viandes doivent se détacher toutes seules des os.","Laissez tiédir, retirez les os, la peau du pied de veau et les gros nerfs, et effilochez grossièrement les viandes. Réservez le bouillon filtré.","Tassez les viandes dans une terrine, couvrez avec le bouillon de cuisson et laissez prendre 12 h (une nuit) au réfrigérateur : le collagène du pied de veau forme une gelée ferme.","Le jour même : coupez les pommes de terre en quartiers, enrobez-les de graisse de canard et de sel, et rôtissez-les 40 min à 210 °C en les retournant à mi-cuisson, jusqu’à ce qu’elles soient croustillantes.","Démoulez le potjevleesch, coupez-le en tranches épaisses et servez-le froid avec les pommes de terre chaudes, la laitue et les cornichons."],"tags":["préparation à l’avance","repas froid","riche en collagène","batch cooking","familial","sans gluten"],"seasons":["ete","printemps"],"technique":"braise","flavors":["acidule","umami","frais"],"tips":"Pourquoi c’est nutritif : la gelée naturelle est faite du collagène du pied de veau et des os, riche en glycine et en proline ; trois viandes différentes dans un seul plat. Se garde 5 jours au réfrigérateur."},{"id":"fb-chou-farci-auvergnat","name":"Chou farci auvergnat au porc, veau et riz, braisé au bouillon","description":"Un chou vert entier reconstitué feuille à feuille autour d’une farce de chair à saucisse, de veau, de riz et d’herbes, puis braisé longuement dans un bouillon d’os avec du lard.","emoji":"🥬","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":45,"cookTime":150,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"chou-vert","qty":1,"unit":"piece","note":"chou de Milan bien pommé"},{"id":"porc-hache","qty":600,"unit":"g","note":"chair à saucisse"},{"id":"veau-hache","qty":400,"unit":"g"},{"id":"riz-rond","qty":200,"unit":"g"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"oignon","qty":2,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"persil","qty":15,"unit":"g"},{"id":"lardons","qty":150,"unit":"g","note":"ou fines tranches de lard"},{"id":"bouillon-boeuf","qty":1000,"unit":"ml"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"thym","qty":3,"unit":"brin"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Retirez les grosses feuilles extérieures abîmées et creusez le trognon. Blanchissez le chou entier 10 min dans une grande marmite d’eau bouillante salée, puis égouttez-le tête en bas.","Cuisez le riz 10 min à l’eau bouillante salée (il finira de cuire dans le chou) et égouttez-le. Mélangez à la main les deux viandes, le riz, les œufs, un oignon et l’ail hachés, le persil, la muscade, 1 c. à café de sel et du poivre.","Posez le chou sur un linge, écartez délicatement les feuilles une à une. Retirez le cœur, hachez-le et ajoutez-le à la farce. Garnissez le centre d’une boule de farce, puis glissez de la farce entre chaque couche de feuilles en refermant à mesure.","Ficelez le chou en croix (ou enveloppez-le dans le linge noué) pour qu’il garde sa forme.","Dans une cocotte, faites revenir les lardons, l’autre oignon et la carotte en rondelles 5 min. Posez le chou dessus, versez le bouillon et le thym, couvrez et laissez braiser 2 h à feu doux (ou 2 h au four à 160 °C), en arrosant de temps en temps.","Coupez le chou en parts comme un gâteau et servez avec une louche de bouillon réduit et les lardons."],"tags":["mijoté","familial","batch cooking","week-end","réconfortant","sans gluten"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","umami","herbace"],"tips":"Pourquoi c’est nutritif : le chou braisé devient très digeste et garde ses vitamines dans le bouillon d’os que l’on sert avec. Les parts restantes se réchauffent au four dans leur bouillon."},{"id":"fb-gateau-foies-volaille-coulis","name":"Gâteau de foies blonds de volaille, coulis de tomate et pommes vapeur","description":"La spécialité de la Bresse : foies de volaille mixés avec du lait, des œufs et de la crème, cuits au bain-marie en un flan aérien, nappés d’un coulis de tomate et servis avec des pommes vapeur.","emoji":"🍮","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":50,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"foie-volaille","qty":450,"unit":"g","note":"foies blonds, dénervés"},{"id":"oeuf","qty":5,"unit":"piece"},{"id":"lait","qty":300,"unit":"ml"},{"id":"creme-liquide","qty":150,"unit":"ml"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"persil","qty":10,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"fecule-mais","qty":1,"unit":"cas"},{"id":"beurre","qty":30,"unit":"g"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"huile-olive","qty":20,"unit":"ml"},{"id":"pomme-de-terre","qty":700,"unit":"g"},{"id":"jambon-blanc","qty":4,"unit":"piece","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer le four à 160 °C et beurrez un moule à charlotte ou un plat à gratin profond.","Mixez finement les foies avec l’ail et le persil. Ajoutez les œufs un à un, puis la fécule, le lait, la crème, la muscade, 1 c. à café de sel et du poivre. Passez le mélange au tamis pour qu’il soit parfaitement lisse.","Versez dans le moule, posez-le dans un plat rempli d’eau chaude à mi-hauteur et enfournez 45 à 50 min au bain-marie : la lame d’un couteau doit ressortir propre et le centre rester légèrement tremblotant.","Coulis : faites fondre l’échalote ciselée dans l’huile 3 min, ajoutez les tomates, salez et laissez réduire 15 min à feu doux, puis mixez.","Cuisez les pommes de terre épluchées 20 min à la vapeur.","Laissez reposer le gâteau 5 min, démoulez-le, nappez-le de coulis et servez-le en parts avec les pommes vapeur et le jambon."],"tags":["abats","économique","four","sans gluten","familial"],"seasons":[],"technique":"four","flavors":["cremeux","umami"],"tips":"Pourquoi c’est nutritif : le foie de volaille est l’une des sources les plus riches en vitamine A, folates et B12, et sa douceur une fois mixé avec lait et œufs le rend facile à aimer. Le gâteau se mange aussi froid."}]`);export{e as default};